WITH enriched AS (SELECT s.*, a.balance, a.status FROM transactions s LEFT JOIN accounts a ON s.account_id = a.id) SELECT CASE WHEN balance >= 80000 THEN 'LARGE' ELSE 'SMALL' END AS balance_tier, DATE_TRUNC('MONTH', txn_time) AS activity_month, SUM(amount) AS total_amount, MAX(txn_time) AS last_seen, GROUPING_ID() AS grouping_level FROM enriched GROUP BY GROUPING SETS ((CASE WHEN balance >= 80000 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('MONTH', txn_time)), (CASE WHEN balance >= 80000 THEN 'LARGE' ELSE 'SMALL' END));
